// Wash HUD (client/wash.lua): 'wash' shows / updates it, 'washHide' hides it.
(() => {
    const hud = document.getElementById('washHud');
    const $ = id => document.getElementById(id);
    const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
    let lastRows = '';

    const row = r => {
        const cls = ['wash-row', r.done && 'is-done', r.active && 'is-active', r.warn && 'is-warn'].filter(Boolean).join(' ');
        const key = r.kbd ? `<kbd>${esc(r.kbd)}</kbd>` : '';
        const value = r.value != null ? `<span class="wash-row__value">${esc(r.value)}</span>` : '';
        return `<div class="${cls}">${key}<span class="wash-row__name">${esc(r.label)}</span>${value}</div>`;
    };

    window.addEventListener('message', ({ data: msg }) => {
        if (!msg) return;
        if (msg.action === 'washHide') {
            hud.hidden = true;
            lastRows = '';
            return;
        }
        if (msg.action !== 'wash') return;

        const d = msg.data || {};
        const pct = Math.max(0, Math.min(100, d.pct || 0));
        $('washTitle').textContent = d.title || '';
        $('washSub').textContent = d.sub || '';
        $('washPct').textContent = Math.floor(pct);
        $('washBar').style.width = pct + '%';
        $('washIconHose').hidden = !!d.auto;
        $('washIconAuto').hidden = !d.auto;
        hud.classList.toggle('is-flowing', !!d.flowing);

        const rows = (d.rows || []).map(row).join('');
        if (rows !== lastRows) {
            $('washList').innerHTML = rows;
            lastRows = rows;
        }
        hud.hidden = false;
    });
})();

// BEGIN BUNDLED WASH AUDIO (generated by scripts/bundle_wash_audio.py)
window.CrimsonWashAudioData={"water":"data:audio/wav;base64,","foam":"data:audio/wav;base64,"};
// Dedicated wash loops: independent of particle rendering and HUD visibility.
(() => {
    if (window.CrimsonWashAudioLoaded) return;
    const files = window.CrimsonWashAudioData || { water: 'audio/wash_water.ogg', foam: 'audio/wash_foam.ogg' };
    const playing = new Map();
    let lastMessage = 0;
    const reportedErrors = new Set();
    let resource = typeof GetParentResourceName === 'function' ? GetParentResourceName() : null;
    let readyConfirmed = false;
    let lastReadyAttempt = -Infinity;
    const report = (status, code) => {
        if (!resource || typeof fetch !== 'function') return;
        if (status === 'ready') {
            if (readyConfirmed || Date.now() - lastReadyAttempt < 1000) return;
            lastReadyAttempt = Date.now();
        }
        fetch(`https://${resource}/washAudioStatus`, {
            method: 'POST', headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ status, code: code || '' }),
        }).then(response => { if (status === 'ready' && response.ok) readyConfirmed = true; }).catch(() => {});
    };
    const reportError = code => {
        if (reportedErrors.has(code)) return;
        reportedErrors.add(code);
        report('error', code);
    };

    const stop = id => {
        const entry = playing.get(id);
        if (!entry) return;
        entry.audio.pause();
        entry.audio.removeAttribute('src');
        entry.audio.load();
        playing.delete(id);
    };
    const stopAll = () => [...playing.keys()].forEach(stop);

    window.addEventListener('message', ({ data }) => {
        if (!data || data.action !== 'washAudio') return;
        // The Lua sender supplies the exact resource name, including renamed
        // installs and CEF builds without GetParentResourceName.
        if (typeof data.resource === 'string' && /^[a-zA-Z0-9_.-]{1,96}$/.test(data.resource)) resource = data.resource;
        report('ready');
        lastMessage = Date.now();
        const seen = new Set();
        for (const stream of (Array.isArray(data.streams) ? data.streams : []).slice(0, 4)) {
            // Object.hasOwn is unavailable in older FiveM CEF builds. A missing
            // method here aborts every message before any Audio can be created.
            if (!stream || !Object.prototype.hasOwnProperty.call(files, stream.kind)) continue;
            const id = String(stream.id);
            const volume = Math.max(0, Math.min(1, Number(stream.volume) || 0));
            if (!volume || id.length > 32 || seen.has(id)) continue;
            seen.add(id);
            let entry = playing.get(id);
            if (entry && entry.kind !== stream.kind) { stop(id); entry = null; }
            if (!entry) {
                const audio = new Audio(files[stream.kind]);
                audio.loop = true;
                audio.preload = 'auto';
                entry = { kind: stream.kind, audio, lastAttempt: -Infinity };
                playing.set(id, entry);
                audio.addEventListener('error', () => {
                    if (playing.get(id) !== entry) return;
                    const embedded = files[stream.kind].indexOf('data:audio/wav;') === 0;
                    reportError(embedded || (audio.error && audio.error.code === 3) ? 'decode' : 'file');
                });
                audio.addEventListener('playing', () => {
                    if (playing.get(id) === entry && !entry.confirmed) {
                        entry.confirmed = true;
                        report('playing', stream.kind);
                    }
                });
            }
            entry.audio.volume = volume;
            if (entry.audio.paused && Date.now() - entry.lastAttempt >= 1000) {
                entry.lastAttempt = Date.now();
                try {
                    const result = entry.audio.play();
                    if (result && result.catch) result.catch(error => {
                        if (playing.get(id) !== entry || (error && error.name === 'AbortError')) return;
                        reportError(error && error.name === 'NotAllowedError' ? 'blocked' : 'play');
                    });
                } catch (error) {
                    reportError('play');
                }
            }
        }
        for (const id of playing.keys()) if (!seen.has(id)) stop(id);
    });
    // No heartbeat after a cancelled/failed client loop must leave an audio loop.
    setInterval(() => { if (Date.now() - lastMessage > 750) stopAll(); }, 250);
    window.addEventListener('pagehide', stopAll);
    window.CrimsonWashAudioLoaded = true;
    report('ready');
})();
